import itertools
from typing import Dict, List
from problems import Sat

def solve(instance: Dict) -> bool:
    Sat.validate(instance)
    m = instance['num_vars']
    clauses = instance['clauses']
    # any empty clause -> unsat
    for c in clauses:
        if len(c) == 0:
            return False
    # iterate assignments 0..2^m-1
    for bits in range(1 << m):
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = (bits >> var) & 1
                if lit > 0 and val == 1:
                    clause_ok = True
                    break
                if lit < 0 and val == 0:
                    clause_ok = True
                    break
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False
EOF"}

